'use strict';

// MODULES //

var sqrtf = require( '@stdlib/math/base/special/sqrtf' );
var sincosf = require( '@stdlib/math/base/special/sincosf' ).assign;
var PINF = require( '@stdlib/constants/float32/pinf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var poly1 = require( './rational_p1q1.js' );
var poly2 = require( './rational_p2q2.js' );
var polyC = require( './rational_pcqc.js' );
var polyS = require( './rational_psqs.js' );


// VARIABLES //

var ONE_DIV_SQRT_PI = f32( 0.5641895835477563 );
var x1 = f32( 2.4048255576957727686e+00 );
var x2 = f32( 5.5200781102863106496e+00 );
var x11 = f32( 6.160e+02 );
var x12 = f32( -1.42444230422723137837e-03 );
var x21 = f32( 1.4130e+03 );
var x22 = f32( 5.46860286310649596604e-04 );
var ZERO = f32( 0.0 );
var ONE = f32( 1.0 );
var FOUR = f32( 4.0 );
var EIGHT = f32( 8.0 );

// `sincosf` workspace:
var sc = [ 0.0, 0.0 ];


// MAIN //

/**
* Computes the zero-order Bessel function of the first kind for a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} evaluated Bessel function
*
* @example
* var v = j0f( 0.0 );
* // returns 1.0
*
* @example
* var v = j0f( 1.0 );
* // returns ~0.765
*
* @example
* var v = j0f( Infinity );
* // returns 0.0
*
* @example
* var v = j0f( -Infinity );
* // returns 0.0
*
* @example
* var v = j0f( NaN );
* // returns NaN
*/
function j0f( x ) {
	var rc;
	var rs;
	var y2;
	var r;
	var y;
	var f;

	if ( x < ZERO ) {
		x = -x;
	}
	if ( x === PINF ) {
		return ZERO;
	}
	if ( x === ZERO ) {
		return ONE;
	}
	if ( x <= FOUR ) {
		y = f32( x * x );
		r = f32( poly1( y ) );
		f = f32( f32( x+x1 ) * f32( f32(x - f32(x11/f32(256.0))) - x12 ) );
		return f32( f * r );
	}
	if ( x <= EIGHT ) {
		y = f32( ONE - ( f32( x*x )/f32( 64.0 ) ) );
		r = f32( poly2( y ) );
		f = f32( ( x+x2 ) * f32( f32(x - f32(x21/f32(256.0))) - x22 ) );
		return f32( f * r );
	}
	y = f32( EIGHT / x );
	y2 = f32( y * y );
	rc = f32( polyC( y2 ) );
	rs = f32( polyS( y2 ) );
	f = f32( ONE_DIV_SQRT_PI / sqrtf(x) );

	/*
	* What follows is really just:
	*
	* ```
	* var z = x - pi/4;
	* return f * (rc * cos(z) - y * rs * sin(z));
	* ```
	*
	* But using the addition formulae for sin and cos, plus the special values for sin/cos of `π/4`.
	*/
	sincosf( x, sc, 1, 0 );
	return f32( f * ( f32( rc * f32(sc[1]+sc[0]) ) - f32( f32(y*rs) * f32(sc[0]-sc[1]) ) ) );
}


// EXPORTS //

module.exports = j0f;
